const p = $input.first().json;
const cfg = $('Config').first().json;
const dryRun = cfg.dry_run === true || cfg.dry_run === 'true';
const live = cfg.divar_live_submit === true || cfg.divar_live_submit === 'true';

function validate(p) {
  const errors = [];
  if (!p.used_phone) errors.push('not_used_phone');
  if (!p.publish_to_divar) errors.push('publish_to_divar_disabled');
  const title = String(p.divar_title || p.name || '').trim();
  if (title.length < 3) errors.push('missing_title');
  const price = Number(String(p.divar_price || '').replace(/,/g, ''));
  if (!Number.isFinite(price) || price <= 0) errors.push('invalid_price');
  const imgs = (p.images || []).filter(u => /^https?:\/\//.test(String(u)));
  if (!imgs.length) errors.push('missing_real_image');
  if (!String(p.divar_city || '').trim()) errors.push('missing_city');
  if (!String(p.divar_category_slug || '').trim()) errors.push('missing_divar_category');
  return { ok: !errors.length, errors, imgs, title, price };
}

const v = validate(p);
if (!v.ok) {
  return [{ json: { result: 'ERROR', validation_errors: v.errors, product: p, telegram_error: true } }];
}

const token = String(p.divar_post_token || '').trim();
if (token) {
  return [{ json: { result: 'DUPLICATE_OR_UPDATE', action: 'update', post_token: token, product: p, dry_run: dryRun, divar_live_submit: live, divar_layer: { title: v.title, price: v.price, city_slug: p.divar_city, category_slug: p.divar_category_slug, image_urls: v.imgs } } }];
}

const layer = {
  title: v.title,
  price: v.price,
  city_slug: p.divar_city,
  category_slug: p.divar_category_slug,
  description: [p.description, p.body_condition, p.accessories, p.warranty].filter(Boolean).join('\n'),
  image_urls: v.imgs,
  attributes: { condition: p.condition, battery_health: p.battery_health, storage: p.storage, color: p.color, repair_history: p.repair_history, registered: p.registered === 'yes', box: p.box === 'yes' },
  wc_sku: p.sku,
  wc_product_id: p.product_id,
};

if (dryRun || !live) {
  return [{ json: { result: 'DRY_RUN_OK', action: 'preview', product: p, divar_layer: layer, divar_live_submit: false, note: 'Map divar_layer to Kenar schema from Swagger before live submit' } }];
}

return [{ json: { result: 'READY_FOR_LIVE', action: 'create', product: p, divar_layer: layer, divar_live_submit: true, divar_endpoint: 'POST https://open-api.divar.ir/experimental/open-platform/posts/new-v2', required_permission: 'SUBMIT_POST' } }];
